from abc import ABC, abstractmethod

class Drawable(ABC):
    @abstractmethod
    def draw(self):
        pass

    @abstractmethod
    def resize(self, factor):
        pass

class Square(Drawable):
    def __init__(self, side):
        self.side = side

    def draw(self):
        print(f'Square with side {self.side}')

    def resize(self, factor):
        self.side *= factor

s = Square(4)
s.draw()
s.resize(2)
s.draw()

from typing import Protocol

class Printable(Protocol):
    def print_info(self) -> None: ...

class Book:
    def __init__(self, title):
        self.title = title

    def print_info(self):
        print(f'Book: {self.title}')

def show(item: Printable):
    item.print_info()

show(Book('Dune'))

from typing import Protocol

class Speaker(Protocol):
    def speak(self) -> str: ...

class Dog:
    def speak(self):
        return 'Woof!'

class Cat:
    def speak(self):
        return 'Meow!'

class Robot:
    def speak(self):
        return 'Beep boop.'

def make_noise(obj: Speaker):
    print(obj.speak())

for thing in [Dog(), Cat(), Robot()]:
    make_noise(thing)

